from ortools.linear_solver import pywraplp

# Create solver
solver = pywraplp.Solver.CreateSolver('CBC')
if not solver:
    print("status: infeasible")
    print("objective: N/A")
else:
    # Extract data
    n = data["num_locations"]
    depot = data["depot_location"]
    dist = data["distance_matrix"]

    # Sets
    V = range(n)  # 0-indexed: locations 0 to 6 (representing 1 to 7)
    depot_idx = depot - 1  # Convert to 0-indexed

    # Decision variables
    # x[i,j] = 1 if travel from i to j
    x = {}
    for i in V:
        for j in V:
            if i != j:
                x[i, j] = solver.BoolVar(f"x_{i}_{j}")

    # u[i] = position of location i in the tour (for subtour elimination)
    u = {}
    for i in V:
        u[i] = solver.IntVar(1, n, f"u_{i}")

    # Objective: minimize total distance
    objective = solver.Objective()
    for i in V:
        for j in V:
            if i != j:
                objective.SetCoefficient(x[i, j], dist[i][j])
    objective.SetMinimization()

    # Constraint 1: Each location is entered exactly once
    for j in V:
        constraint = solver.Constraint(1, 1, f"enter_{j}")
        for i in V:
            if i != j:
                constraint.SetCoefficient(x[i, j], 1)

    # Constraint 2: Each location is left exactly once
    for i in V:
        constraint = solver.Constraint(1, 1, f"leave_{i}")
        for j in V:
            if i != j:
                constraint.SetCoefficient(x[i, j], 1)

    # Constraint 3: Subtour elimination (MTZ formulation)
    for i in V:
        if i != depot_idx:
            for j in V:
                if j != depot_idx and i != j:
                    # u[i] - u[j] + n * x[i,j] <= n - 1
                    constraint = solver.Constraint(-solver.infinity(), n - 1, f"mtz_{i}_{j}")
                    constraint.SetCoefficient(u[i], 1)
                    constraint.SetCoefficient(u[j], -1)
                    constraint.SetCoefficient(x[i, j], n)

    # Constraint 4: Fix depot position
    constraint = solver.Constraint(1, 1, "depot_position")
    constraint.SetCoefficient(u[depot_idx], 1)

    # Solve
    status = solver.Solve()

    # Output results
    if status == pywraplp.Solver.OPTIMAL:
        print(f"status: optimal")
        print(f"objective: {solver.Objective().Value()}")

        # Print the tour
        tour = [depot_idx]
        current = depot_idx
        for _ in range(n - 1):
            for j in V:
                if j != current and x[current, j].solution_value() > 0.5:
                    tour.append(j)
                    current = j
                    break
        tour.append(depot_idx)
        # Convert to 1-indexed for display
        tour_display = [loc + 1 for loc in tour]
        print(f"Tour: {' -> '.join(map(str, tour_display))}")
    else:
        print(f"status: infeasible")
        print(f"objective: N/A")
